 readonly ImageSourcePlugin plugin;readonly ToolEditorContext context;readonly ToolConfigurationState state;readonly Func<Dictionary<string,JsonElement>> read;readonly Action<Dictionary<string,JsonElement>> apply;readonly Func<string,string> text;
 readonly W.ListBox list=new(){Name="ImageSourceLocalList",BorderThickness=new Thickness(0),Background=Brushes.Transparent,HorizontalContentAlignment=System.Windows.HorizontalAlignment.Stretch,AllowDrop=true};
