 public ImageSourceConfigurationList(ImageSourcePlugin plugin,ToolEditorContext context,ToolConfigurationState state,Func<Dictionary<string,JsonElement>> read,Action<Dictionary<string,JsonElement>> apply,Func<string,string> text,ToolConfigurationExecution execution){
  Resources.MergedDictionaries.Add(new ResourceDictionary{Source=new Uri("/VisionPluginContracts;component/Resources/ConfigurationControls.xaml",UriKind.Relative)});
