  count.Foreground=new SolidColorBrush(Color.FromRgb(102,102,102));count.Margin=new Thickness(15,1,0,0);header.Children.Add(count);W.Grid.SetColumn(mode,1);header.Children.Add(mode);W.Grid.SetColumn(expand,3);header.Children.Add(expand);
