 static JsonElement Value<T>(T value)=>JsonSerializer.SerializeToElement(value);
 string[] Paths()=>ImageSourcePlugin.ReadPaths(read()["ImagePaths"].GetString()??"[]");
 void Save<T>(string key,T value){var next=new Dictionary<string,JsonElement>(read());next[key]=Value(value);apply(next);fingerprint="";Refresh();}
 void Report(string operation,string diagnostic)=>state.ReportDiagnostic(new("ImageList",operation,"Lang_LocalImgList",diagnostic));
 void AddDialog(){var result=(context.ConfigurationFiles??new WpfConfigurationFileService()).Select(Window.GetWindow(this),new(plugin.Manifest.Id,read()["CurrentImagePath"].GetString()??"",text("图像文件")+"|*.bmp;*.jpeg;*.jpg;*.png;*.tif;*.tiff",text("Open"),true));if(result.Status==ConfigurationFileStatus.Selected){AddFiles(result.Paths);if(result.Paths.Count>0){var stored=(context.ConfigurationFiles??new WpfConfigurationFileService()).Remember(plugin.Manifest.Id,result.Paths[0]);if(!stored.Success)Report("Remember",stored.Diagnostic??"History write failed.");}}else if(result.Status is ConfigurationFileStatus.Failed or ConfigurationFileStatus.Unsupported)Report("Select",result.Diagnostic??result.Status.ToString());}
 void AddFolderDialog(){var result=(context.ConfigurationFolders??new WpfConfigurationFolderService()).Select(Window.GetWindow(this),new(""));if(result.Status==ConfigurationFileStatus.Selected&&result.Path is {} path){try{AddFiles(FilesIn(path,1));}catch(Exception error)when(error is IOException or UnauthorizedAccessException){Report("AddFolder",error.Message);}}else if(result.Status is ConfigurationFileStatus.Failed or ConfigurationFileStatus.Unsupported)Report("AddFolder",result.Diagnostic??result.Status.ToString());}
 static IEnumerable<string> FilesIn(string directory,int depth){foreach(var path in Directory.GetFileSystemEntries(directory).OrderBy(p=>p.Length).ThenBy(p=>p)){if(File.Exists(path)){if(new[]{".JPG",".JPEG",".BMP",".PNG",".TIF",".TIFF"}.Contains(Path.GetExtension(path).ToUpperInvariant()))yield return path;}else if(depth<=1)foreach(var child in FilesIn(path,depth+1))yield return child;}}
 public void AddFiles(IEnumerable<string> files){var paths=Paths().ToList();foreach(var path in files){if(paths.Contains(path,StringComparer.Ordinal))continue;try{var node=context.Node with{Parameters=read()};_=plugin.LoadPreview(node,path,context.BaseDirectory,context.Resources?.Invoke());paths.Add(path);}catch(Exception error)when(error is IOException or ArgumentException or NotSupportedException or System.Runtime.InteropServices.ExternalException){Report("AddImage",error.Message);break;}}Save("ImagePaths",JsonSerializer.Serialize(paths));}
 public void Delete(string path){var values=new Dictionary<string,JsonElement>(read());var paths=Paths().Where(p=>p!=path).ToArray();values["ImagePaths"]=Value(JsonSerializer.Serialize(paths));values["SelectedPaths"]=Value(JsonSerializer.Serialize(ImageSourcePlugin.ReadPaths(values["SelectedPaths"].GetString()??"[]").Where(p=>p!=path)));if(values["CurrentImagePath"].GetString()==path)values["CurrentImagePath"]=Value("");apply(values);fingerprint="";Refresh();}
 public void Clear(){var values=new Dictionary<string,JsonElement>(read());values["ImagePaths"]=Value("[]");values["SelectedPaths"]=Value("[]");values["CurrentImagePath"]=Value("");apply(values);fingerprint="";Refresh();}
 public void Select(string path){var values=new Dictionary<string,JsonElement>(read());var ordered=Paths();if(values["ExecuteType"].GetInt32()==2){var selected=ImageSourcePlugin.ReadPaths(values["SelectedPaths"].GetString()??"[]");ordered=ordered.Where(selected.Contains).ToArray();}int index=Array.IndexOf(ordered,path);if(index<0)return;values["CurrentImagePath"]=Value(values["AutoPlay"].GetBoolean()?ordered[(index+ordered.Length-1)%ordered.Length]:path);apply(values);if(state.Find("CurrentImagePath") is {} node)state.SetProgrammatic(node,"CurValue",values["CurrentImagePath"].GetString()??"");if(context.Scope is null)Report("SelectRun","Procedure execution scope is unavailable.");else context.Scope.RequestRun(context.Node.Id);RefreshCounter();}
 public void ReturnFirst(){var values=new Dictionary<string,JsonElement>(read());var paths=Paths();if(values["ExecuteType"].GetInt32()==2){var selected=ImageSourcePlugin.ReadPaths(values["SelectedPaths"].GetString()??"[]");paths=paths.Where(selected.Contains).ToArray();}if(paths.Length==0)return;values["CurrentImagePath"]=Value(values["AutoPlay"].GetBoolean()?paths[^1]:paths[0]);apply(values);if(state.Find("CurrentImagePath") is {} node)state.SetProgrammatic(node,"CurValue",values["CurrentImagePath"].GetString()??"");first.Tag=true;scrollOffset=0;if(list.Items.Count>0)list.ScrollIntoView(list.Items[0]);RefreshThumbnails();}
 void RefreshCounter(){var values=read();var paths=Paths();int current=0;if(context.Scope!=null){var images=plugin.GetImages(context.Node with{Parameters=values},context.Scope);current=images.ToList().FindIndex(i=>i.Selected)+1;}count.Text=text("Lang_ImgSoc")+" ("+current+"/"+paths.Length+")";}
 public void Refresh(){RefreshCounter();var values=read();var next=values["ImagePaths"].GetString()+"|"+values["SelectedPaths"].GetString()+"|"+values["ExecuteType"].ToString()+"|"+values["PixelFormat"].ToString();if(next==fingerprint)return;fingerprint=next;refreshing=true;try{mode.SelectedIndex=values["ExecuteType"].GetInt32()-1;list.Items.Clear();thumbnails.Clear();var selected=ImageSourcePlugin.ReadPaths(values["SelectedPaths"].GetString()??"[]").ToHashSet(StringComparer.Ordinal);var paths=Paths();first.Visibility=paths.Length==0?Visibility.Collapsed:Visibility.Visible;foreach(var path in paths){var item=new W.ListBoxItem{Style=(Style)FindResource("ImageSourceListItem"),Tag=path,Padding=new Thickness(1)};var grid=new W.Grid{Width=72,Height=52,Margin=new Thickness(2),Background=Brushes.White,ToolTip=path};var image=new W.Image{Stretch=Stretch.Uniform};thumbnails.Add((image,grid,path));grid.Children.Add(image);var check=new W.CheckBox{Style=(Style)FindResource("SmallCheckBoxStyle"),IsChecked=selected.Contains(path),VerticalAlignment=System.Windows.VerticalAlignment.Top,HorizontalAlignment=System.Windows.HorizontalAlignment.Left,Margin=new Thickness(6,2.5,0,0),Visibility=mode.SelectedIndex==1?Visibility.Visible:Visibility.Collapsed};check.Click+=(_,_)=>{var all=ImageSourcePlugin.ReadPaths(read()["SelectedPaths"].GetString()??"[]").ToHashSet(StringComparer.Ordinal);if(check.IsChecked==true)all.Add(path);else all.Remove(path);Save("SelectedPaths",JsonSerializer.Serialize(Paths().Where(all.Contains)));};grid.Children.Add(check);var delete=new W.Button{Style=(Style)FindResource("ImageSourceDelete"),Width=16,Height=16,VerticalAlignment=System.Windows.VerticalAlignment.Top,HorizontalAlignment=System.Windows.HorizontalAlignment.Right,Visibility=Visibility.Collapsed};delete.Click+=(_,e)=>{Delete(path);e.Handled=true;};grid.MouseEnter+=(_,_)=>delete.Visibility=Visibility.Visible;grid.MouseLeave+=(_,_)=>delete.Visibility=Visibility.Collapsed;grid.Children.Add(delete);item.Content=grid;list.Items.Add(item);}RefreshCounter();}finally{refreshing=false;}RefreshThumbnails();}
 void RefreshThumbnails(){int first=(int)scrollOffset,count=(int)Math.Ceiling((list.ActualWidth>0?list.ActualWidth:Width)/76);for(int index=0;index<thumbnails.Count;index++){var item=thumbnails[index];if(index<first||index>=first+count){item.Image.Source=null;continue;}if(item.Image.Source!=null)continue;try{var data=plugin.LoadPreview(context.Node with{Parameters=read()},item.Path,context.BaseDirectory,context.Resources?.Invoke());item.Image.Source=BitmapSource.Create(data.Width,data.Height,96,96,data.Format==VisionCore.ImagePixelFormat.Rgb24?PixelFormats.Rgb24:PixelFormats.Gray8,null,data.Pixels.ToArray(),data.Stride);}catch(Exception error)when(error is IOException or ArgumentException or NotSupportedException){item.Frame.ToolTip=error.Message;}}}
